async function backgroundAPI(query='',body=null){if(!window.TEMHOA_TOKEN||location.protocol==='file:')throw Error('Hãy mở phần mềm bằng Mo-TemHoa-Mac.command hoặc Mo-TemHoa-Windows.bat để dùng AI.');const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),20000);try{const response=await fetch('/api/background'+query,{method:body?'POST':'GET',headers:{'Content-Type':'application/json','X-TemHoa-Token':window.TEMHOA_TOKEN},body:body?JSON.stringify(body):undefined,signal:controller.signal});const data=await response.json();if(!response.ok)throw Error(data.error||'Không kết nối được bộ AI.');return data}finally{clearTimeout(timeout)}}
