$('aiRun').onclick=async()=>{if(aiBusy||!aiTarget)return;const generation=++aiGeneration;aiBusy=true;syncAIButtons();$('aiStatus').textContent='Đang xử lý… Lần đầu có thể mất vài phút để tải mô hình. Bạn có thể đóng cửa sổ này; ảnh trên tem chưa thay đổi.';try{const status=await backgroundAPI();if(!status.available){$('aiSetup').hidden=false;throw Error('Chưa cài bộ AI. Làm theo hướng dẫn bên dưới rồi thử lại.')}if(generation!==aiGeneration)return;$('aiSetup').hidden=true;const job=await backgroundAPI('',{mode:$('aiMode').value,image:aiTarget.original});const started=Date.now();while(generation===aiGeneration){await new Promise(resolve=>setTimeout(resolve,900));if(generation!==aiGeneration)return;const result=await backgroundAPI('?job='+encodeURIComponent(job.job));if(result.state==='error')throw Error(result.error);if(result.state==='done'){if(!/^data:image\/png;base64,/.test(result.image))throw Error('Kết quả AI không hợp lệ.');const image=await loadGraphic(result.image);if(generation!==aiGeneration)return;aiResult=result.image;aiDraw($('aiAfter'),image);aiBrushHistory=[];$('aiStatus').textContent='Đã xóa nền. Kiểm tra tóc/mép ảnh; dùng cọ Xóa thêm hoặc Giữ lại chi tiết, rồi bấm Áp dụng vào tem.';return}if(Date.now()-started>620000)throw Error('AI mất quá nhiều thời gian. Hãy thử chế độ Nhanh.')}}catch(error){if(generation===aiGeneration)$('aiStatus').textContent=error.name==='AbortError'?'Kết nối AI bị gián đoạn. Hãy kiểm tra cửa sổ chạy phần mềm và thử lại.':error.message}finally{if(generation===aiGeneration){aiBusy=false;syncAIButtons()}}};
