function paintLayerUnit(ctx,L,scale,unit,color='fill'){
 if(unit.kind==='text')textOnlyDraw(ctx,{...L,runs:unit.key==='text-box'?L.runs:L.runs.filter(run=>(run.layerKey||'text-0')===unit.key)},scale,color);
 if(unit.kind==='graphic'){ctx.save();ctx.scale(scale,scale);drawGraphic(ctx,unit.item,color!=='fill');ctx.restore()}
}
function paintLayerStack(ctx,L,scale,paintBackground){
 paintBackground();for(const unit of orderedLayerUnits(L))paintLayerUnit(ctx,L,scale,unit)
}
function layerStackSVG(L,scale,w,h,inner,outer,color){
 const edgePath='<path fill="'+color('edge')+'" fill-rule="evenodd" d="'+contourPath(outer.map((v,i)=>Math.max(0,v-inner[i])),w,h,true)+'"/>';
 const bodyPath=isDesign()?'':'<path fill="'+color('body')+'" fill-rule="evenodd" d="'+contourPath(inner,w,h,true)+'"/>';
 return bodyPath+edgePath+orderedLayerUnits(L).map(unit=>{
  if(unit.kind==='graphic')return graphicsSVG({...L,graphics:[unit.item]},scale);
  const canvas=cv(w,h),ctx=canvas.getContext('2d');paintLayerUnit(ctx,L,scale,unit,'#ffffff');const rgba=ctx.getImageData(0,0,w,h).data,mask=new Uint8Array(w*h);for(let i=0;i<mask.length;i++)mask[i]=rgba[i*4+3]>=128?255:0;
  return '<path fill="'+color('fill')+'" fill-rule="evenodd" d="'+contourPath(mask,w,h,false)+'"/>';
 }).join('\n');
}
