let selectedUnitKey='',layerDragData=null;
const selectedLayerUnits=new Set();
const layerSelectionId=(labelId,key)=>JSON.stringify([labelId,key]);
function activeUnitKey(){return selectedGraphicId||selectedUnitKey}
async function selectLayerUnit(labelId,key,additive=false,preserve=false){
 if(labelOperation||layerBusy)return;
 const selectionId=layerSelectionId(labelId,key);
 if(additive&&!preserve){if(!selectedLayerUnits.size&&activeUnitKey())selectedLayerUnits.add(layerSelectionId(activeLabelId,activeUnitKey()));if(selectedLayerUnits.has(selectionId)){selectedLayerUnits.delete(selectionId);const fallback=[...selectedLayerUnits].at(-1);if(fallback){const [owner,unit]=JSON.parse(fallback);await selectLayerUnit(owner,unit,true,true)}else{selectedUnitKey='';selectedGraphicId=null;selectedGraphicSet.clear();positionGraphicOverlays();syncGraphicControls();renderLayersPanel()}return}}else if(!preserve) selectedLayerUnits.clear();
 selectedLayerUnits.add(selectionId);
 if(labelId!==activeLabelId)await activateLabel(labelId);
 selectedUnitKey=key;
 if(key.startsWith('graphic-')){const item=decorations.find(item=>item.id===key);if(!item)return;selectGraphicItems(item);selectedGraphicSet=new Set(decorations.filter(graphic=>selectedLayerUnits.has(layerSelectionId(activeLabelId,graphic.id))).map(graphic=>graphic.id));$('editLayer').value='image'}
 else{selectedGraphicId=null;selectedGraphicSet.clear();$('editLayer').value='text';if(key==='text-box'&&isDesign()&&!designEditing){savedSelection=null;getSelection()?.removeAllRanges()}else if(key==='text-box'||key.startsWith('text-')){const runs=key==='text-box'?(previewSize?.L.runs||[]):(previewSize?.L.runs||[]).filter(run=>(run.layerKey||'text-0')===key);if(runs.length){const start=Math.min(...runs.map(run=>run.textStart)),end=Math.max(...runs.map(run=>run.textEnd));if(Number.isFinite(start)&&Number.isFinite(end)){savedSelection=rangeOffsets($('temEditor'),{start,end});$('temEditor').focus({preventScroll:true});const selection=getSelection();selection.removeAllRanges();selection.addRange(savedSelection)}}}}
 positionGraphicOverlays();syncGraphicControls();renderLayersPanel();
}
async function reorderLayerUnit(labelId,key,targetKey,after=false){
 if(layerBusy||labelOperation||graphicDrag||labelDrag||key===targetKey)return;
 if(labelId!==activeLabelId)await activateLabel(labelId);
 layerBusy=true;
 try{
  recordHistory();const L=previewSize?.L||layout(),order=orderedLayerUnits(L).map(unit=>unit.key),from=order.indexOf(key);
  if(from<0||!order.includes(targetKey))return;
  order.splice(from,1);const index=order.indexOf(targetKey);order.splice(index+(after?0:1),0,key);
  $('layerStack').value=JSON.stringify({...readLayerStack(),order});selectedUnitKey=key;
  // Keep graphic hit-testing and the older image tools in the same relative order.
  decorations.sort((a,b)=>order.indexOf(a.id)-order.indexOf(b.id));
  await preview();recordHistory();syncGraphicControls();
 }finally{layerBusy=false;renderLayersPanel()}
}
function renderLayersPanel(){
 if(!previewSize)return;
 const host=$('layersList'),scroll=host.scrollTop;host.replaceChildren();
 [...labels].reverse().forEach(label=>{
  const L=label.id===activeLabelId?previewSize.L:label.size?.L;if(!L)return;
  const section=document.createElement('section');section.className='layerSection';
  const title=document.createElement('button');title.type='button';title.className='layerSectionTitle';title.textContent='Tem '+(labels.indexOf(label)+1);title.onclick=()=>activateLabel(label.id).then(renderLayersPanel);section.append(title);
  const stack=readLayerStack(label.id===activeLabelId?$('layerStack').value:label.settings.layerStack||'{}');
  for(const unit of orderedLayerUnits(L,stack).reverse()){
   const row=document.createElement('div');row.className='layerRow';row.tabIndex=0;row.setAttribute('role','button');row.dataset.labelId=label.id;row.dataset.unitKey=unit.key;
   const selected=selectedLayerUnits.size?selectedLayerUnits.has(layerSelectionId(label.id,unit.key)):label.id===activeLabelId&&activeUnitKey()===unit.key;row.classList.toggle('selected',selected);row.setAttribute('aria-pressed',String(selected));
   const name=unit.kind==='text'?'Chữ · '+(unit.text.trim()||'Dòng trống'):unit.kind==='background'?unit.text:(unit.item.kind==='image'?'Ảnh':graphicNames[unit.item.kind]||'Emoji');
   row.title=name+' · Shift + bấm để chọn/bỏ chọn nhiều lớp';row.setAttribute('aria-label',name);
   const grip=document.createElement('span');grip.className='layerGrip';grip.textContent='⋮⋮';grip.draggable=true;grip.title='Kéo để đổi lớp';
   grip.ondragstart=event=>{layerDragData={labelId:label.id,key:unit.key};event.dataTransfer.setData('text/plain',unit.key);event.dataTransfer.effectAllowed='move'};
   grip.ondragend=()=>{layerDragData=null;host.querySelectorAll('.layerRow').forEach(node=>node.classList.remove('dropBefore','dropAfter'))};
   row.append(grip);
   if(unit.kind==='graphic'&&unit.item.kind==='image'){const img=document.createElement('img');img.className='layerThumb';img.src=unit.item.src;img.alt='';img.draggable=false;row.append(img)}
   else{const icon=document.createElement('span');icon.className='layerThumb layerIcon';icon.textContent=unit.kind==='text'?'T':unit.kind==='background'?'▱':(emojiIcons[unit.item.kind]?.[0]||legacyEmoji[unit.item.kind]||'✦');row.append(icon)}
   const text=document.createElement('span');text.className='layerName';text.textContent=name;row.append(text);
   if(unit.kind==='graphic'){const lock=document.createElement('button');lock.type='button';lock.className='layerLock';lock.textContent=unit.item.locked?'🔒':'🔓';lock.title=unit.item.locked?'Mở khóa hình':'Khóa hình';lock.onclick=async event=>{event.stopPropagation();await selectLayerUnit(label.id,unit.key);await imageLockButton.onclick();renderLayersPanel()};row.append(lock)}
   row.onclick=event=>selectLayerUnit(label.id,unit.key,event.shiftKey).catch(error=>$('status').textContent=error.message);
   row.onkeydown=event=>{if(event.target!==row)return;if(['Enter',' '].includes(event.key)){event.preventDefault();selectLayerUnit(label.id,unit.key,event.shiftKey).catch(error=>$('status').textContent=error.message)}else if(event.altKey&&['ArrowUp','ArrowDown'].includes(event.key)){event.preventDefault();selectLayerUnit(label.id,unit.key).then(()=>moveObjectLayer(event.key==='ArrowUp'?1:-1)).catch(error=>$('status').textContent=error.message)}};
   row.ondragover=event=>{if(layerDragData?.labelId!==label.id)return;event.preventDefault();const after=event.clientY>row.getBoundingClientRect().top+row.offsetHeight/2;row.classList.toggle('dropBefore',!after);row.classList.toggle('dropAfter',after)};
   row.ondragleave=()=>row.classList.remove('dropBefore','dropAfter');
   row.ondrop=event=>{event.preventDefault();row.classList.remove('dropBefore','dropAfter');const drag=layerDragData;layerDragData=null;if(!drag||drag.labelId!==label.id)return;reorderLayerUnit(label.id,drag.key,unit.key,event.clientY>row.getBoundingClientRect().top+row.offsetHeight/2).catch(error=>$('status').textContent=error.message)};
   section.append(row);
  }
  host.append(section);
 });host.scrollTop=scroll;
}
const beforeUnitLayerMove=moveObjectLayer;
moveObjectLayer=async function(delta,graphicOnly=false){
 const key=activeUnitKey(),L=previewSize?.L;if(!key||!L)return beforeUnitLayerMove(delta,graphicOnly);
 const order=orderedLayerUnits(L).map(unit=>unit.key),index=order.indexOf(key),next=index+delta;
 if(index<0||next<0||next>=order.length)return;
 return reorderLayerUnit(activeLabelId,key,order[next],delta<0);
};
const beforeUnitLayerButtons=syncLayerButtons;syncLayerButtons=function(){beforeUnitLayerButtons();const key=activeUnitKey(),L=previewSize?.L;if(!key||!L)return;const order=orderedLayerUnits(L).map(unit=>unit.key),index=order.indexOf(key);for(const prefix of ['layer','menuLayer']){$(prefix+'Up').disabled=layerBusy||index<0||index===order.length-1;$(prefix+'Down').disabled=layerBusy||index<=0}};
const beforeUnitPanelZoom=zoom;zoom=function(){beforeUnitPanelZoom();renderLayersPanel()};
$('previewArea').addEventListener('pointerdown',()=>selectedLayerUnits.clear(),true);
$('temEditor').addEventListener('pointerup',()=>{captureSelection();selectedUnitKey='text-box';renderLayersPanel();syncLayerButtons()});
const beforeUnitOverlays=positionGraphicOverlays;positionGraphicOverlays=function(){beforeUnitOverlays();const order=previewSize?.L?orderedLayerUnits(previewSize.L).map(unit=>unit.key):[];$('labelSurface').querySelectorAll('.graphicOverlay').forEach(box=>box.style.zIndex=6+order.indexOf(box.dataset.graphicId))};
renderLayersPanel();

